#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""ホームページのブログ記事を書いて、確認用のPRまで作る。

なぜ main に直接入れないのか
---------------------------
`main` に push すると GitHub Actions がそのまま本番へ出してしまう。
記事は会社の信用に直結するので、**人が読んでからマージする**という取り決めがある。
このスクリプトはブランチを切ってPRを作るところで止まる。プレビューは自動で当たるので、
中元さんはPRのプレビューURLで仕上がりを見てからマージできる。

数字について
-----------
実績の件数や金額は、AIに作らせると平気で嘘を書く。
なのでこのスクリプトは**具体的な数値を書かせない**。実績値を入れたい記事は、
人が後からPRに追記する。

使い方
------
    python3 ~/.fukkaru/blog.py            # 記事を1本書いてPRを作る
    FUKKARU_BLOG_MODE=dry python3 ~/.fukkaru/blog.py   # 保存だけ。gitには触らない
    FUKKARU_BLOG_MODE=shindan python3 scripts/blog/blog.py   # 公開済みの記事を測るだけ（鍵もgitも使わない）
    FUKKARU_BLOG_MODE=naosu   python3 scripts/blog/blog.py   # 公開済みの記事に自動の直しを当てる（ファイルを書き換える）
    FUKKARU_BLOG_MODE=kakinaoshi     python3 scripts/blog/blog.py   # 公開済みの記事を1本、AIで書き直してPRを作る（毎日13時）
    FUKKARU_BLOG_MODE=kakinaoshi-dry python3 scripts/blog/blog.py   # 書き直しの試し。gitには触らないが、記事と記録のファイルは書き換える
                                                                   # （Mac の ~/fukkaru-landing では走らせない。rsync した写しで）
"""
