def log(msg: str) -> None:
    LOGF.parent.mkdir(parents=True, exist_ok=True)
    line = "[%s] %s" % (date.today().strftime("%Y-%m-%d"), msg)
    print(line)
    with LOGF.open("a", encoding="utf-8") as f:
        f.write(line + "\n")


def gen_text(prompt: str) -> str:
    """Gemini でテキストを作る。モデルが使えなければ次の候補を試す。"""
    body = {"contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {"temperature": 0.9, "maxOutputTokens": 24576}}
    # 「考える」ぶんも同じ枠から出ていく（2026-09-05 に投稿案で分かったこと）。
    # 実測（gemini-2.5-flash・本番のプロンプト）:
    #   制限なし   合計 8,429 ／ 本文 4,166字
    #   2048まで   合計 6,771 ／ 本文 4,347字  ← 短くならない。むしろ長い
    #   1024まで   合計 5,492 ／ 本文 3,865字  ← ここまで削ると本文が痩せる
    # **記事の中身は削らない。**考えるぶんだけ 2048 に抑える。
    THINK = {"thinkingBudget": 2048}
    last = ""
    for model in TEXT_MODELS:
        if not model:
            continue
        url = ("https://generativelanguage.googleapis.com/v1beta/models/"
               f"{model}:generateContent")
        payload = None
        # 1回目はこの指定つき。知らないモデルは400を返すので、そのときは指定なしで。
        for think in (THINK, None):
            cfg = dict(body["generationConfig"])
            if think:
                cfg["thinkingConfig"] = think
            req = urllib.request.Request(
                url, data=json.dumps({**body, "generationConfig": cfg}).encode("utf-8"),
                headers={"x-goog-api-key": KEY, "Content-Type": "application/json"},
                method="POST")
            try:
                with urllib.request.urlopen(req, timeout=300) as r:
                    payload = json.loads(r.read().decode("utf-8"))
                break
            except urllib.error.HTTPError as e:
                detail = e.read().decode("utf-8", "replace")[:200]
                if e.code == 400 and think:
                    continue
                last = f"{model} -> {e.code}: {detail}"
                payload = None
                break
            except Exception as e:
                last = f"{model} -> {e}"
                payload = None
                break
        if payload is None:
            continue
        try:
            cand = payload["candidates"][0]
            # 途中で切れた答えは受け取らない。切れたJSONは必ず後で壊れる
            if cand.get("finishReason") == "MAX_TOKENS":
                u = payload.get("usageMetadata", {})
                last = (f"{model} -> 枠に収まらず途中で切れました"
                        f"（考えたぶん {u.get('thoughtsTokenCount')}）")
                continue
            parts = cand["content"]["parts"]
            text = "".join(p.get("text", "") for p in parts).strip()
            if text:
                return text
            last = f"{model} -> 応答にテキストなし"
        except urllib.error.HTTPError as e:
            last = f"{model} -> {e.code}: {e.read().decode('utf-8', 'replace')[:200]}"
        except Exception as e:
            last = f"{model} -> {e}"
    raise RuntimeError(last or "テキストを作れませんでした")


def extract_json(s: str) -> dict:
    """```json ...``` で囲まれていても中身を取り出す。"""
    s = s.strip()
    m = re.search(r"```(?:json)?\s*(.+?)\s*```", s, re.S)
    if m:
        s = m.group(1)
    start, end = s.find("{"), s.rfind("}")
    if start < 0 or end < 0:
        raise ValueError("JSONが見つかりません：" + s[:200])
    return json.loads(s[start:end + 1])


def existing() -> list[dict]:
    out = []
    for f in sorted(ARTICLES.glob("*.json")):
        try:
            out.append(json.loads(f.read_text(encoding="utf-8")))
        except Exception:
            pass
    return out


# **狙い.txt はリポジトリ側の1か所だけ**（2026-09-13）。
# Mac側にも写しがあり、153行と196行で中身がずれていました。毎日動くのはリポジトリ側です
TARGETS = Path(os.environ.get("FUKKARU_TARGETS")
               or (HOME / "fukkaru-landing" / "scripts" / "blog" / "狙い.txt"))

# **「次にどれを書くか」の位置は、リポジトリの中のものを本物にします。**
#
# 2026-09-03、位置が2か所にあってずれました。Macから手で4本書いたのに
# 自動ぶんの位置は動かず、翌日と翌々日が同じ狙いをなぞる形になっていました。
# 見張りを足すより、**1つにしてしまうほうが確かです。**
# リポジトリの中にあれば、記事と一緒にコミットされて自動ぶんにも伝わります
# （その仕組みは元からありました。Macが別のファイルを見ていただけです）。
_REPO_CURSOR = REPO / "scripts" / "blog" / "狙い_いまの位置.txt"
CURSOR = (Path(os.environ["FUKKARU_CURSOR"]) if os.environ.get("FUKKARU_CURSOR")
          else (_REPO_CURSOR if _REPO_CURSOR.exists()
                else HOME / ".fukkaru" / "狙い_いまの位置.txt"))


def read_targets() -> list[tuple[str, str]]:
    """狙いの一覧（`~/.fukkaru/狙い.txt`）を読む。無ければ空を返す"""
    if not TARGETS.exists():
        return []
    out: list[tuple[str, str]] = []
    for line in TARGETS.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or ":" not in line:
            continue
        svc, _, area = line.partition(":")
        svc, area = svc.strip(), area.strip()
        if svc and area:
            out.append((svc, area))
    return out


def advance_target() -> None:
    """記事が1本できたときだけ、狙いを次へ進める"""
    if MODE == "dry":
        # **試し運転で位置を進めない。**位置は本物のファイルを指すようになったので、
        # 進めてしまうと次の日の狙いが1つ飛びます（2026-09-03、手で戻しました）
        return
    targets = read_targets()
    if not targets:
        return
    try:
        i = int(CURSOR.read_text(encoding="utf-8").strip())
    except (OSError, ValueError):
        i = 0
    try:
        CURSOR.parent.mkdir(parents=True, exist_ok=True)
        CURSOR.write_text(str((i + 1) % len(targets)) + "\n", encoding="utf-8")
    except OSError:
        pass          # 覚えられなくても、書けたこと自体は変わらない


def pick_target(done: list[dict]) -> tuple[str, str]:
    """次に書く狙いを決める。

    **1位を狙うなら、薄く広げてはいけない。**
    以前は「いちばん記事が薄いサービス×地域」を選んでいたので、
    10サービス×8地域＝80通りに1日1本ずつ配られ、どこにも積み上がらなかった
    （2026-09-02、家具組立の記事が4本あるのに検索表示がゼロだった）。

    いまは `~/.fukkaru/狙い.txt` を上から順にまわる。
    同じ行を何度も書けば、そこに記事が集まる。中元さんが自分で変えられる。
    """
    # 環境変数で1回だけ上書きできる（例：FUKKARU_BLOG_TARGET="不用品の運搬:富士市"）
    want = (os.environ.get("FUKKARU_BLOG_TARGET") or "").strip()
    if want:
        parts = want.split(":", 1)
        return parts[0].strip(), (parts[1].strip() if len(parts) > 1 else AREAS[0])

    targets = read_targets()
    if targets:
        # 既存の記事数から数えると、狙いの途中から始まってしまう。
        # どこまで進んだかは自分で覚えておく（1行の数字だけのファイル）
        try:
            i = int(CURSOR.read_text(encoding="utf-8").strip())
        except (OSError, ValueError):
            i = 0
        # **進めるのは記事が書けたあと**（advance_target）。
        # ここで進めると、失敗した日に狙いが1つ飛ぶ（2026-09-02に実際に飛んだ）
        return targets[i % len(targets)]

    # 一覧が無いときだけ、昔どおり薄いところを選ぶ
    blob = json.dumps(done, ensure_ascii=False)
    service = min(SERVICES, key=lambda w: (blob.count(w), SERVICES.index(w)))
    area = min(AREAS, key=lambda w: (blob.count(w), AREAS.index(w)))
    return service, area


# 記事の切り口。**同じ切り口が続くとタイトルの型もそろってしまう**ので、
# 書いた本数で順ぐりに回す。1周するまで同じ切り口は来ない。
